import { sql, type BuildExtraConfigColumns } from 'drizzle-orm';
import {
  customType,
  pgTable,
  timestamp,
  unique,
  uuid,
  type PgColumnBuilderBase,
  type PgTableExtraConfigValue,
} from 'drizzle-orm/pg-core';

/** PostgreSQL `bytea` as a Node `Buffer` (ciphertext, wrapped keys). */
export const bytea = customType<{ data: Buffer; driverData: Buffer }>({
  dataType: () => 'bytea',
});

/** The `id` column every table shares: a UUIDv7 generated by the database unless one is given. */
function idColumn() {
  return uuid('id')
    .primaryKey()
    .default(sql`app.uuid_v7()`);
}

function timestamps() {
  return {
    createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
    updatedAt: timestamp('updated_at', { withTimezone: true })
      .notNull()
      .defaultNow()
      .$onUpdate(() => new Date()),
  };
}

type TenantColumns = {
  id: ReturnType<typeof idColumn>;
  tenantId: ReturnType<ReturnType<typeof uuid>['notNull']>;
} & ReturnType<typeof timestamps>;

/**
 * A table owned by one tenant. Adds the UUIDv7 `id`, `tenant_id NOT NULL`, timestamps and
 * `UNIQUE (tenant_id, id)`, so other tables can point at it with a composite foreign key
 * `(tenant_id, x_id)` and a row can never reference another tenant's row.
 *
 * Row level security is not declared here: drizzle-kit cannot express FORCE. Every migration that
 * creates a tenant table appends `tenantPolicies(name)`, and the RLS catalog test fails the build
 * if one forgets.
 */
export function tenantTable<
  TName extends string,
  TColumns extends Record<string, PgColumnBuilderBase>,
>(
  name: TName,
  columns: TColumns,
  extraConfig?: (
    table: BuildExtraConfigColumns<TName, TColumns & TenantColumns, 'pg'>,
  ) => PgTableExtraConfigValue[],
) {
  const shared = {
    id: idColumn(),
    tenantId: uuid('tenant_id').notNull(),
    ...timestamps(),
  };
  return pgTable(name, { ...shared, ...columns }, (table) => [
    unique(`${name}_tenant_id_id_key`).on(table.tenantId, table.id),
    ...(extraConfig?.(table as never) ?? []),
  ]);
}

function quoteIdentifier(identifier: string): string {
  return `"${identifier.replaceAll('"', '""')}"`;
}

/**
 * SQL that turns a table into a tenant-isolated one: row level security ENABLED and FORCED (so the
 * table owner is subject to it too) plus the `tenant_isolation` policy. The policy reads
 * `current_setting('app.tenant_id')` WITHOUT `missing_ok`, so a query outside `withTenant` raises
 * instead of returning rows: it fails closed. `column` is `id` for the `tenant` table itself.
 * Statements are separated by drizzle's breakpoint marker so the migrator runs them one by one.
 */
export function tenantPolicies(table: string, options: { column?: string } = {}): string {
  const name = quoteIdentifier(table);
  const column = quoteIdentifier(options.column ?? 'tenant_id');
  const predicate = `${column} = current_setting('app.tenant_id')::uuid`;
  return [
    `ALTER TABLE ${name} ENABLE ROW LEVEL SECURITY;`,
    `ALTER TABLE ${name} FORCE ROW LEVEL SECURITY;`,
    `CREATE POLICY "tenant_isolation" ON ${name} USING (${predicate}) WITH CHECK (${predicate});`,
  ].join('\n--> statement-breakpoint\n');
}

export interface ClinicalPolicyOptions {
  patientColumn?: string;
  authorColumn?: string;
  visibilityColumn?: string;
  /**
   * What the table passes as the template kind: the name of a column (default `template_kind`);
   * `null` for entries that follow the general ceiling (anamnesis, documents, consent); or a
   * constant such as `{ constant: 'prescription' }` for prescriptions, which never follow sharing.
   */
  templateKind?: string | null | { constant: string };
}

function sqlLiteral(value: string): string {
  return `'${value.replaceAll("'", "''")}'`;
}

/**
 * SQL for the database backstop of clinical access (ADR-003, ADR-002): two RESTRICTIVE policies,
 * combined with AND with `tenant_isolation`, so a row is visible only if
 *
 * - `clinical_professionals_only`: the transaction acts as a health professional
 *   (`app.professional_id` is set only for an active profile with a recorded matricula), and
 * - `clinical_scope`: `app.clinical_readable` allows this entry (author, treating professional,
 *   or the sharing scope).
 *
 * An owner, admin or reception transaction has no professional id, so it sees zero rows even if the
 * application layer had a bug. Apply it, after `tenantPolicies`, to every table that holds
 * clinical content.
 */
export function clinicalPolicies(table: string, options: ClinicalPolicyOptions = {}): string {
  const name = quoteIdentifier(table);
  const patient = quoteIdentifier(options.patientColumn ?? 'patient_id');
  const author = quoteIdentifier(options.authorColumn ?? 'author_professional_id');
  const visibility = quoteIdentifier(options.visibilityColumn ?? 'visibility');
  const template = options.templateKind;
  const templateExpression =
    template === null
      ? 'NULL::text'
      : typeof template === 'object'
        ? `${sqlLiteral(template.constant)}::text`
        : quoteIdentifier(template ?? 'template_kind');

  return [
    `CREATE POLICY "clinical_professionals_only" ON ${name} AS RESTRICTIVE USING (nullif(current_setting('app.professional_id', true), '') IS NOT NULL);`,
    `CREATE POLICY "clinical_scope" ON ${name} AS RESTRICTIVE USING (app.clinical_readable(${patient}, ${author}, ${visibility}, ${templateExpression}));`,
  ].join('\n--> statement-breakpoint\n');
}
